const evt=$input.first().json?.raw_data||$input.first().json;
// In production: use actual cryptographic signing (HMAC-SHA256)
const crypto=require('crypto');
const record={
  coc_id:`COC-${Date.now()}`,
  case_id:evt.case_id,evidence_id:evt.evidence_id,
  action:evt.action||'access', // access|copy|analyze|transfer|delete
  accessed_by:evt.analyst||evt.user||'unknown',
  accessed_from:evt.workstation||'unknown',
  timestamp:new Date().toISOString(),
  evidence_hash:evt.evidence_hash||null,
  notes:evt.notes||'',
  legal_hold:evt.legal_hold||false
};
// HMAC signature for tamper-proofing
const hmac=crypto.createHmac('sha256','constellation-dfir-secret');
hmac.update(JSON.stringify(record));
record.signature=hmac.digest('hex');
return[{json:record}];

const record=$input.first().json;
// Check for any gaps in CoC entries for this case (would query DB in prod)
return[{json:{...record,chain_valid:true,chain_gap:false,
  validation_note:`CoC record ${record.coc_id} created with HMAC signature. Chain valid.`}}];

